  ('Q124625460', 'Portuguese invasion of Bahrain', 'The Portuguese capture of Bahrain from the Jabrids Emirate was a campaign that took place in 1521 by Portuguese forces under the command of António Correia.', 1521, NULL, NULL, NULL, NULL, NULL, 'year', '1521', 30, 'https://en.wikipedia.org/wiki/Portuguese_invasion_of_Bahrain'),
