  ('Q7267163', 'Qatari–Bahraini War', 'The Qatari–Bahraini War (Arabic: الحرب القطرية البحرينية), also known as the Qatari War of Independence (Arabic: حرب الاستقلال القطرية), was an armed conflict that took place in 1867 and 1868 in the Persian Gulf. The conflict pitted Bahrain and Abu Dhabi against Qatar.', 1867, NULL, NULL, 1868, NULL, NULL, 'year', '1867–1868', 39, 'https://en.wikipedia.org/wiki/Qatari%E2%80%93Bahraini_War'),
